-- =============================================================
-- [OUTPUT] 23. model_evaluation_metrics
-- Model performance metrics computed after each pipeline run.
-- =============================================================
CREATE TABLE model_evaluation_metrics (
    id              BIGINT       GENERATED ALWAYS AS IDENTITY,
    as_of_date      DATE         NOT NULL,
    model_name      VARCHAR(30)  NOT NULL,
    metric_name     VARCHAR(30)  NOT NULL,
    metric_value    DECIMAL(10,6),
    horizon_band    VARCHAR(20),
    computed_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    CONSTRAINT uq_metric UNIQUE (as_of_date, model_name, metric_name, horizon_band)
);

COMMENT ON TABLE model_evaluation_metrics IS 'Model performance metrics — WMAPE, MAE, RMSE, MAPE, R² per model per horizon band';
COMMENT ON COLUMN model_evaluation_metrics.model_name IS 'ensemble | lgbm | chronos | nhits | tft';
COMMENT ON COLUMN model_evaluation_metrics.metric_name IS 'wmape | mae | rmse | mape | r2';
COMMENT ON COLUMN model_evaluation_metrics.horizon_band IS '1-7 | 8-14 | 15-21 | 22-42 | NULL (overall)';

CREATE INDEX model_evaluation_metrics_idx_as_of ON model_evaluation_metrics (as_of_date);
CREATE INDEX model_evaluation_metrics_idx_model ON model_evaluation_metrics (model_name);
